<?php
declare(strict_types=1);
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/vendor_theme.php';session_start();
$vendorId=filter_input(INPUT_GET,'rid',FILTER_VALIDATE_INT)?:(int)($_SESSION['vendor_id']??0);if(!$vendorId){http_response_code(400);exit('Missing vendor.');}$_SESSION['vendor_id']=$vendorId;
$stmt=$pdo->prepare("SELECT * FROM restaurants WHERE id=? AND status='active'");$stmt->execute([$vendorId]);$vendor=$stmt->fetch();if(!$vendor){http_response_code(404);exit('Storefront not found.');}$cart=$_SESSION['carts'][$vendorId]??[];
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['items'])){foreach($_POST['items'] as $itemId=>$details){$qty=max(0,min(20,(int)($details['qty']??0)));if(!$qty)continue;$stmt=$pdo->prepare('SELECT * FROM menu_items WHERE id=? AND restaurant_id=?');$stmt->execute([(int)$itemId,$vendorId]);$item=$stmt->fetch();if(!$item)continue;$variants=json_decode($item['variant_options']?:'[]',true)?:[['label'=>'Standard','price'=>$item['price']]];$label=(string)($details['variant']??'');$price=null;foreach($variants as $variant)if(hash_equals((string)$variant['label'],$label)){$price=(float)$variant['price'];break;}if($price===null)continue;$key=$itemId.':'.hash('sha256',$label);$cart[$key]=['id'=>(int)$itemId,'name'=>$item['name'],'variant'=>$label,'unit_price'=>$price,'qty'=>($cart[$key]['qty']??0)+$qty];}$_SESSION['carts'][$vendorId]=$cart;}
if(isset($_GET['remove'])){unset($cart[(string)$_GET['remove']]);$_SESSION['carts'][$vendorId]=$cart;header('Location: /cart.php?rid='.$vendorId);exit;}$_SESSION['cart']=$cart;$total=array_sum(array_map(fn($row)=>$row['qty']*$row['unit_price'],$cart));
