<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Your cart · <?= htmlspecialchars($vendor['name']) ?></title><link rel="stylesheet" href="/assets/css/storefront.css"></head><body style="<?= htmlspecialchars(vendor_theme_style($vendor)) ?>"><main class="checkout-shell"><header class="checkout-head"><a href="/shop/<?= htmlspecialchars($vendor['slug']) ?>">← Menu</a><div><span class="step-label">Step 1 of 2</span><h1>Your order</h1></div></header>
<?php if(!$cart):?><section class="panel empty"><h2>Your cart is empty</h2><p>Choose something from <?= htmlspecialchars($vendor['name']) ?>.</p><a class="primary-button" href="/shop/<?= htmlspecialchars($vendor['slug']) ?>">Browse menu <span>→</span></a></section><?php else:?><section class="panel"><?php foreach($cart as $key=>$item):?><div class="line-item"><div><strong><?= htmlspecialchars($item['name']) ?></strong><br><small><?= (int)$item['qty'] ?> × <?= htmlspecialchars($item['variant']) ?> · R<?= number_format($item['unit_price'],2) ?></small><br><a href="/cart.php?rid=<?= $vendorId ?>&remove=<?= urlencode($key) ?>">Remove</a></div><strong>R<?= number_format($item['qty']*$item['unit_price'],2) ?></strong></div><?php endforeach;?><div class="total"><span>Total</span><span>R<?= number_format($total,2) ?></span></div></section>
